"""Book-level permissions for shared books in multi-user deployments.

The admin workspace is the shared catalogue.  A normal user's own workspace
remains private and fully editable; this model only controls access to books in
the shared catalogue.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Literal

from .models import CurrentUser

BookPermissionLevel = Literal["none", "read", "edit"]
BookDefaultLevel = Literal["none", "read"]
BOOK_PERMISSION_LEVELS = frozenset({"none", "read", "edit"})
BOOK_DEFAULT_LEVELS = frozenset({"none", "read"})


@dataclass(frozen=True, slots=True)
class BookPermission:
    """Creation capability plus shared-catalogue defaults and overrides."""

    create: bool = True
    default: BookDefaultLevel = "none"
    books: tuple[tuple[str, BookPermissionLevel], ...] = ()

    def level_for(self, book_id: str) -> BookPermissionLevel:
        for candidate, level in self.books:
            if candidate == book_id:
                return level
        return self.default

    def books_dict(self) -> dict[str, BookPermissionLevel]:
        return dict(self.books)


# Missing, malformed, and newly created records all preserve the pre-feature
# ability to create a personal book, but expose no admin book implicitly.
DEFAULT_BOOK_PERMISSION = BookPermission()
ADMIN_BOOK_PERMISSION = BookPermission(create=True, default="read")


def normalize_book_permission(raw: Any) -> BookPermission:
    """Return a fail-closed canonical permission from any persisted shape.

    The external reference implementation had earlier ``mode/actions`` shapes.
    We accept those conservatively for operators who tried that build: delete is
    collapsed to edit, and an absent/unknown legacy shape never grants access.
    """

    if not isinstance(raw, dict):
        return DEFAULT_BOOK_PERMISSION

    if any(key in raw for key in ("create", "default", "books")):
        create = raw.get("create", True) is True
        default_raw = raw.get("default")
        default: BookDefaultLevel = default_raw if default_raw in BOOK_DEFAULT_LEVELS else "none"
        books: list[tuple[str, BookPermissionLevel]] = []
        raw_books = raw.get("books")
        if isinstance(raw_books, dict):
            for raw_id, raw_level in raw_books.items():
                book_id = str(raw_id or "").strip()
                if not book_id:
                    continue
                if raw_level == "delete":
                    raw_level = "edit"
                if raw_level in BOOK_PERMISSION_LEVELS:
                    books.append((book_id, raw_level))
        return BookPermission(create=create, default=default, books=tuple(books))

    mode = str(raw.get("mode") or "none")
    actions = raw.get("actions") if isinstance(raw.get("actions"), dict) else {}
    create = actions.get("create", True) is True
    writable = actions.get("edit") is True or actions.get("delete") is True
    level: BookPermissionLevel = "edit" if writable else "read"
    if mode == "all":
        # A legacy all-mode is honoured because it was an explicit stored
        # choice, but it can never imply write access for future books.
        return BookPermission(create=create, default="read")
    if mode == "list" and isinstance(raw.get("book_ids"), (list, tuple, set)):
        seen: set[str] = set()
        books = []
        for item in raw["book_ids"]:
            book_id = str(item or "").strip()
            if book_id and book_id not in seen:
                seen.add(book_id)
                books.append((book_id, level))
        return BookPermission(create=create, books=tuple(books))
    return BookPermission(create=create)


def public_permission_dict(permission: BookPermission) -> dict[str, Any]:
    return {
        "create": permission.create,
        "default": permission.default,
        "books": permission.books_dict(),
    }


def canonical_book_permission(raw: Any) -> dict[str, Any]:
    return public_permission_dict(normalize_book_permission(raw))


def permission_for_user(user: CurrentUser) -> BookPermission:
    if user.is_admin:
        return ADMIN_BOOK_PERMISSION
    from .identity import get_user

    record = get_user(user.username) or {}
    return normalize_book_permission(record.get("book_permission"))


__all__ = [
    "ADMIN_BOOK_PERMISSION",
    "BOOK_DEFAULT_LEVELS",
    "BOOK_PERMISSION_LEVELS",
    "DEFAULT_BOOK_PERMISSION",
    "BookDefaultLevel",
    "BookPermission",
    "BookPermissionLevel",
    "canonical_book_permission",
    "normalize_book_permission",
    "permission_for_user",
    "public_permission_dict",
]

import { readFile } from "node:fs/promises";
import { config } from "$lib/server/config";
import type { Route } from "./types";

let ROUTES: Route[] = [];
let loaded = false;

async function loadPolicy(): Promise<Route[]> {
	const path = config.LLM_ROUTER_ROUTES_PATH;
	const text = await readFile(path, "utf8");
	const arr = JSON.parse(text) as Route[];
	if (!Array.isArray(arr)) {
		throw new Error("Routes config must be a flat array of routes");
	}
	const seen = new Set<string>();
	for (const r of arr) {
		if (!r?.name || !r?.description || !r?.primary_model) {
			throw new Error(`Invalid route entry: ${JSON.stringify(r)}`);
		}
		if (seen.has(r.name)) {
			throw new Error(`Duplicate route name: ${r.name}`);
		}
		seen.add(r.name);
	}
	ROUTES = arr;
	loaded = true;
	return ROUTES;
}

export async function getRoutes(): Promise<Route[]> {
	if (!loaded) await loadPolicy();
	return ROUTES;
}

export function resolveRouteModels(
	routeName: string,
	routes: Route[],
	fallbackModel: string
): { candidates: string[] } {
	const sel = routes.find((r) => r.name === routeName) || routes.find((r) => r.name === "default");
	if (!sel) return { candidates: [fallbackModel] };
	const fallbacks = Array.isArray(sel.fallback_models) ? sel.fallback_models : [];
	return { candidates: [sel.primary_model, ...fallbacks] };
}

# astrid-approval

[![License: MIT OR Apache-2.0](https://img.shields.io/badge/License-MIT%20OR%20Apache--2.0-blue.svg)](../../LICENSE-MIT)
[![MSRV: 1.94](https://img.shields.io/badge/MSRV-1.94-blue)](https://www.rust-lang.org)

**Human-in-the-loop approval for sensitive agent operations.**

This crate provides the pieces Astrid uses to gate a risky action behind explicit human confirmation: a typed vocabulary of sensitive actions, scoped auto-approvals (allowances), spending budgets, and the manager that drives a request to a decision. The kernel's approval path consumes these types; the crate holds no kernel state of its own.

## Not a unified security gate

Astrid's security is **decomposed**. There is no single interceptor that every action funnels through (an unwired prototype of that idea, `SecurityInterceptor`, was removed; see issue #991, "Define the canonical security-enforcement model"). Authorization is enforced by independent, per-area mechanisms, each fail-closed:

- the **WASM sandbox**: a capsule has no ambient authority, so every effect is a host call;
- the **manifest allowlist gate** on every host call (`check_file_read` / `check_net_connect` / `check_host_process`), with path-traversal and SSRF defenses;
- the **IPC publish/subscribe ACL** and per-principal routing;
- **capability tokens** (`astrid-capabilities`), principal-scoped, expiry-checked, and globally revocable;
- the **budgets and allowances** in this crate.

This crate is the human-in-the-loop layer of that model, not the model itself.

## What's here

**`SensitiveAction`**: the typed vocabulary of gated operations (file read / delete / write-outside-sandbox, command execution, network request, data transmission, capability grant, MCP tool call, and capsule effects). Each variant carries typed context and is assigned a risk level.

**Allowances (`AllowanceStore`, `AllowancePattern`)**: scoped, user-granted auto-approvals so a repeated action is not re-prompted. They are:

- **principal-scoped**: Alice's allowance never matches Bob's invocation;
- **session- or workspace-scoped**: a workspace allowance (`session_only = false`) survives session end and is pinned to its workspace root, so an allowance granted in `/project-a` cannot match an action in `/project-b`;
- **atomic single-use** when `max_uses` is set: under concurrency exactly one caller may consume a single-use allowance;
- **traversal- and shell-safe**: a `..` path component, or a command carrying shell operators (`;`, `|`, `&&`, `$(`, backticks, redirects), is rejected at the pattern layer and forced back to explicit approval.

The nine `AllowancePattern` variants (`ExactTool`, `ServerTools`, `FilePattern`, `NetworkHost`, `CommandPattern`, `WorkspaceRelative`, `Custom`, `CapsuleCapability`, `CapsuleWildcard`) match via `globset`.

**`ApprovalManager`**: drives the flow. It consults existing allowances first, prompts a registered `ApprovalHandler` only when needed, and translates the decision into an outcome. If no human is available the action becomes a `DeferredResolution` and queues; it is never silently skipped.

**Budgets (`BudgetTracker`, `WorkspaceBudgetTracker`)**: per-action and per-session USD ceilings enforced with an atomic check-and-reserve, so two racing callers cannot both pass the check and then both debit. A cancelled future refunds automatically via a drop guard. The dual budget requires both the session and the workspace to allow.

## Decisions and their effects

`ApprovalDecision` ranges over Allow Once / Allow Session / Allow Workspace / Allow Always / Deny. The session and workspace decisions create allowances in this crate. "Allow Always" is fulfilled by the **kernel**, which holds the runtime signing key and the capability store and mints a persistent capability token; this crate only records the decision and leaves the token minting to the caller.

## Future, not shipped

Cryptographic capability **delegation** and **per-action attenuated tokens** (a child action receiving a token strictly narrower than its parent's) are a planned direction, not a current feature. Do not read the types here as providing them today.

## Usage

```toml
[dependencies]
astrid-approval = { workspace = true }
```

```rust
use astrid_approval::{ApprovalDecision, ApprovalRequest, SensitiveAction};

// Classify a risky action and wrap it in a request with context.
let action = SensitiveAction::FileDelete {
    path: "/home/user/report.txt".to_string(),
};
let request = ApprovalRequest::new(action, "removing a stale report");

// Decisions are explicit; a denial carries a reason.
let decision = ApprovalDecision::Deny {
    reason: "out of scope".to_string(),
};
assert!(!decision.is_approved());
```

Frontends implement the `ApprovalHandler` trait (`request_approval`, `is_available`) to present prompts; the kernel registers the handler on the `ApprovalManager`.

## Development

```bash
cargo test -p astrid-approval
```

